<?php
declare(strict_types=1);
require_once __DIR__.'/engine.php';require_once __DIR__.'/ai/route.php';
function cleanTechnology(array $route,array $c,array $o):array{
 if(!array_is_list($route))fail('Технология должна быть списком операций');$clean=[];
 foreach($route as $op){if(!is_array($op))fail('Некорректная операция');$op=productionItem($op);if(($op['type']??'')==='cut'||($op['domain']??'assembly')==='preparation')fail('Работы подготовки ведутся в отдельной комплектации, а не в технологии пошива');$id=textField($op,'id',96,true);if(!preg_match('/^[a-zA-Z0-9_-]+$/',$id))fail('Некорректный код операции');$type=textField($op,'type',20,true);if(!in_array($type,['sew','special','iron','hand','qc','pack'],true))fail('Неизвестный вид работы');$dep=$op['dependencies']??[];if(!is_array($dep)||!array_is_list($dep))fail('Некорректные зависимости');foreach($dep as $d)if(!is_string($d)||!preg_match('/^[a-zA-Z0-9_-]{1,96}$/',$d))fail('Некорректная связь');$clean[]=['id'=>$id,'name'=>textField($op,'name',300,true),'type'=>$type,'specialization'=>$type==='special'?specialMachineKind($op):null,'seconds'=>numberField($op,'seconds',1,86400,true),'setup_minutes'=>numberField($op,'setup_minutes',0,1440),'dependencies'=>array_values(array_unique($dep)),'source'=>textField($op,'source',600),'batch'=>numberField($op,'batch',1,100000)]+technologyMetadata($op,$c,$o);}
 foreach(routeCheck($clean) as $err)if(!str_starts_with($err,'Нет нормы')&&!str_starts_with($err,'Нет источника')&&!str_starts_with($err,'Нет подтверждения')&&!str_starts_with($err,'Технология ещё'))fail($err);return $clean;
}
function saveTechnology(array $input):array{
 permit(['owner','technologist']);return command('route_save',$input,function(array $c)use($input){$o=orderRecord(textField($input,'order_id',32,true),true);checkRevision((int)$o['revision'],$input);
  if(one("SELECT id FROM tasks WHERE company_id=? AND order_id=? AND state<>'cancelled' AND (released>0 OR state IN ('running','paused','completed','rework','quality')) LIMIT 1",[$c['id'],$o['id']]))fail('Есть начатые партии этой технологии. Её история закреплена; скопируйте технологию в новую цель для изменения состава операций.');
  $route=$input['route']??[];if(!is_array($route))fail('Некорректная технология');$clean=cleanTechnology($route,$c,$o);query('UPDATE orders SET route=?,revision=revision+1 WHERE id=? AND company_id=?',[j(array_merge(productionPreparationRoute(decode($o['route'])),$clean)),$o['id'],$c['id']]);$gens=[];foreach($clean as $op)if(isset($op['ai_origin']))$gens[]=$op['ai_origin']['generation_id'];foreach(array_unique($gens) as $id)query("UPDATE ai_generations SET state='applied' WHERE id=? AND company_id=? AND order_id=?",[$id,$c['id'],$o['id']]);audit('route_saved',['order_id'=>$o['id'],'operations'=>count($clean),'nodes'=>count(array_unique(array_column($clean,'node_id'))),'ai_generations'=>array_values(array_unique($gens))]);return ['saved'=>true];});
}
